using Microsoft.EntityFrameworkCore;

// EF Core 9 Cosmos DB breaking changes applied:
// 1. Discriminator property renamed from "Discriminator" to "$type"
// 2. Synchronous I/O on Cosmos DB now throws by default

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 changed the default discriminator property
        // from "Discriminator" to "$type". For existing documents that already
        // store "Discriminator", explicitly configure the old property name.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}

// Usage example: synchronous Cosmos queries are no longer allowed by default in EF9.
// You MUST convert sync calls to async:
//
// BEFORE (EF8 - throws InvalidOperationException in EF9):
//   var products = db.Products.ToList();
//
// AFTER (EF9):
//   var products = await db.Products.ToListAsync();
//
// If you absolutely cannot use async (e.g., legacy code), opt back in via:
//   optionsBuilder.UseCosmos("...", "db", o => o.AllowSynchronousQueryExecution(true));
// But prefer converting to async.

